<script setup>
import { computed, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { usePlatformStore } from '@/stores/platform'
import { parseDate } from '@/utils/dataAdapters'
const store=usePlatformStore();const filters=reactive({farmId:'',plotNo:'',type:'',status:'',range:[]});const detail=ref(null);const availablePlots=computed(()=>store.plots.filter(x=>!filters.farmId||x.farmId===filters.farmId));const rows=computed(()=>store.alerts.filter(x=>(!filters.farmId||x.farmId===filters.farmId)&&(!filters.plotNo||x.plotNo===filters.plotNo)&&(!filters.type||x.type===filters.type)&&(!filters.status||x.status===filters.status)&&(filters.range?.length!==2||((parseDate(x.occurTime)?.getTime()||0)>=filters.range[0].getTime()&&(parseDate(x.occurTime)?.getTime()||0)<=filters.range[1].getTime()))));function handle(row){ElMessageBox.confirm(`确认将告警 ${row.id} 标记为已处理？`,'处理告警',{type:'warning'}).then(()=>{store.handleAlert(row.id);ElMessage.success('告警已处理')})}
</script>
<template><div class="farmer-page"><div class="page-head"><div><h1 class="page-title">全系统告警</h1><p class="page-subtitle">按农场、地块、类型、状态和时间范围追溯异常。</p></div><div class="page-actions"><span class="status-pill danger">{{store.unhandledAlerts}} 项未处理</span></div></div><section class="content-panel"><div class="filters"><el-select v-model="filters.farmId" clearable placeholder="全部农场" @change="filters.plotNo=''"><el-option v-for="item in store.farms" :key="item.farmId" :label="item.name" :value="item.farmId"/></el-select><el-select v-model="filters.plotNo" clearable placeholder="全部地块"><el-option v-for="item in availablePlots" :key="item.plotNo" :label="`${item.plotNo} · ${item.name}`" :value="item.plotNo"/></el-select><el-select v-model="filters.type" clearable placeholder="告警类型"><el-option v-for="item in ['湿度过低','设备离线','数据未更新']" :key="item" :label="item" :value="item"/></el-select><el-select v-model="filters.status" clearable placeholder="处理状态"><el-option v-for="item in ['未处理','处理中','已处理','已忽略']" :key="item" :label="item" :value="item"/></el-select><el-date-picker v-model="filters.range" type="datetimerange" range-separator="至" start-placeholder="开始时间" end-placeholder="结束时间"/></div><el-table :data="rows" class="compact-table"><el-table-column prop="occurTime" label="发生时间" min-width="165"/><el-table-column prop="farmName" label="农场" min-width="130"/><el-table-column prop="plotName" label="地块" min-width="110"/><el-table-column prop="type" label="类型" min-width="120"><template #default="scope"><span class="status-pill danger">{{scope.row.type}}</span></template></el-table-column><el-table-column prop="deviceId" label="设备ID" width="95"/><el-table-column label="触发值 / 阈值" min-width="130"><template #default="scope">{{scope.row.value}} / {{scope.row.threshold}}</template></el-table-column><el-table-column prop="status" label="状态" width="90"><template #default="scope"><span :class="['status-pill',scope.row.status==='未处理'?'danger':'']">{{scope.row.status}}</span></template></el-table-column><el-table-column label="操作" fixed="right" width="150"><template #default="scope"><el-button link type="primary" @click="detail=scope.row">详情</el-button><el-button v-if="['未处理','处理中'].includes(scope.row.status)" link type="success" @click="handle(scope.row)">标记处理</el-button></template></el-table-column></el-table></section><el-dialog :model-value="Boolean(detail)" title="告警详情与处理过程" width="620px" @close="detail=null"><template v-if="detail"><el-descriptions :column="2" border><el-descriptions-item label="告警ID">{{detail.id}}</el-descriptions-item><el-descriptions-item label="处理状态">{{detail.status}}</el-descriptions-item><el-descriptions-item label="农场">{{detail.farmName}}</el-descriptions-item><el-descriptions-item label="地块">{{detail.plotName}}</el-descriptions-item><el-descriptions-item label="设备">{{detail.deviceId}}</el-descriptions-item><el-descriptions-item label="告警类型">{{detail.type}}</el-descriptions-item><el-descriptions-item label="发生时间">{{detail.occurTime}}</el-descriptions-item><el-descriptions-item label="处理时间">{{detail.handledAt||'尚未处理'}}</el-descriptions-item></el-descriptions><el-timeline class="process"><el-timeline-item v-for="item in detail.process" :key="item" type="primary">{{item}}</el-timeline-item></el-timeline></template></el-dialog></div></template>
<style scoped>.filters{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:18px}.filters .el-select{width:150px}.process{margin-top:22px}</style>
